
function getCitedText(output) {
  const parts = (output?.output || []).flatMap(item => item.content || []).filter(item => item.type === "output_text");
  if (!parts.length) return getText(output);
  return parts.map(part => {
    let text = part.text || "";
    const citations = (part.annotations || []).filter(a => a.type === "url_citation" && /^https?:\/\//.test(a.url || ""));
    for (const a of citations.sort((a, b) => b.start_index - a.start_index)) {
      const label = String(a.title || "Source").replace(/[\[\]\n]/g, " ");
      const link = "[" + label + "](" + a.url.replace(/\)/g, "%29") + ")";
      if (Number.isInteger(a.start_index) && Number.isInteger(a.end_index) && a.start_index >= 0 && a.end_index <= text.length) {
        text = text.slice(0, a.start_index) + " " + link + text.slice(a.end_index);
      } else text += "\n" + link;
    }
    return text;
  }).join("\n").trim();
}
